package id.pterobridge.server;
import org.bukkit.plugin.java.JavaPlugin;
import java.io.*; import java.net.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*;
public final class MultiBridgeServer extends JavaPlugin {
 private static final byte[] MAGIC=new byte[]{'P','B','R','G'}; private volatile boolean running;
 private final ConcurrentMap<String,Session> sessions=new ConcurrentHashMap<>(); private final ConcurrentMap<Long,Socket> players=new ConcurrentHashMap<>(); private final ConcurrentMap<Long,String> playerRoutes=new ConcurrentHashMap<>(); private final ConcurrentMap<Long,CountDownLatch> readyMap=new ConcurrentHashMap<>();
 private final List<ServerSocket> listeners=new CopyOnWriteArrayList<>(); private final ExecutorService pool=Executors.newCachedThreadPool(r->{Thread t=new Thread(r,"PteroBridge-Mux-Server");t.setDaemon(true);return t;}); private final AtomicLong ids=new AtomicLong(1); private String token;
 @Override public void onEnable(){ saveDefaultConfig(); token=getConfig().getString("token",""); if(token.isBlank()){getLogger().severe("Set a non-empty token.");getServer().getPluginManager().disablePlugin(this);return;} running=true;
  for(String entry:getConfig().getStringList("routes")){String[] p=entry.split("=",2);if(p.length!=2)continue;try{String ip=p[0].trim();int port=Integer.parseInt(p[1].trim());if(ip.isEmpty()||port<1||port>65535)continue;String route=ip+":"+port;pool.execute(()->acceptLoop(route,port));}catch(NumberFormatException ignored){}}
  getLogger().info("Experimental multiplexed gateway enabled; no dedicated control port. Keep the primary Paper port separate."); }
 private void acceptLoop(String route,int port){try(ServerSocket ss=new ServerSocket()){ss.setReuseAddress(true);ss.bind(new InetSocketAddress("0.0.0.0",port));listeners.add(ss);getLogger().info("Mux route listening on TCP "+port+" for "+route);while(running){Socket s=ss.accept();s.setTcpNoDelay(true);pool.execute(()->dispatch(s,route));}}catch(IOException e){if(running)getLogger().severe("Listener "+port+" failed: "+e.getMessage());}}
 private void dispatch(Socket s,String route){getLogger().info("[MUX-DIAG] Incoming TCP connection from "+s.getRemoteSocketAddress()+" on "+route);try{DataInputStream in=new DataInputStream(s.getInputStream());byte[] head=new byte[4];in.readFully(head);if(Arrays.equals(head,MAGIC)){getLogger().info("[MUX-DIAG] Recognized tunnel handshake on "+route);handleTunnel(s,in,route);return;} Session sess=sessions.get(route);if(sess==null||!sess.open()){s.close();return;}long id=ids.getAndIncrement();getLogger().info("[MUX-DIAG] Player connection "+id+" accepted; requesting Panel 2 target");players.put(id,s);playerRoutes.put(id,route);CountDownLatch ready=new CountDownLatch(1);readyMap.put(id,ready);try{sess.send((byte)1,id,new byte[0]);}catch(IOException e){closePlayer(id);return;}pool.execute(()->pumpPlayer(id,s,sess,ready,head));}catch(Exception e){getLogger().warning("[MUX-DIAG] Player dispatch failed: "+e.getClass().getSimpleName()+": "+e.getMessage());try{s.close();}catch(IOException ignored){}}}
 private void handleTunnel(Socket s,DataInputStream raw,String route){Session session=null;try{DataInputStream in=raw;DataOutputStream out=new DataOutputStream(new BufferedOutputStream(s.getOutputStream()));String suppliedRoute=in.readUTF();String suppliedToken=in.readUTF();if(!route.equals(suppliedRoute)||!token.equals(suppliedToken)){s.close();getLogger().warning("Rejected mux client (route/token mismatch).");return;}session=new Session(route,s,out);Session old=sessions.put(route,session);if(old!=null)old.close();getLogger().info("Tunnel connected on shared route "+route);while(running&&!s.isClosed()){byte type=in.readByte();long id=in.readLong();int len=in.readInt();if(len<0||len>1048576)throw new IOException("Invalid frame length");byte[] data=in.readNBytes(len);if(data.length!=len)throw new EOFException();Socket p=players.get(id);if(type==2){getLogger().info("[MUX-DIAG] Panel 2 target ready for player "+id);CountDownLatch l=readyMap.get(id);if(l!=null)l.countDown();}else if(type==3){getLogger().warning("[MUX-DIAG] Panel 2 could not open target for player "+id);closePlayer(id);}else if(type==4&&p!=null){try{p.getOutputStream().write(data);p.getOutputStream().flush();}catch(IOException e){closePlayer(id);}}else if(type==5)closePlayer(id);}}catch(Exception e){if(running)getLogger().warning("Tunnel disconnected: "+e.getMessage());}finally{if(session!=null){boolean current=sessions.remove(route,session);session.close();if(current)closeRoutePlayers(route);}else try{s.close();}catch(IOException ignored){}}}
 private void pumpPlayer(long id,Socket p,Session sess,CountDownLatch ready,byte[] prefix){try{if(!ready.await(10,TimeUnit.SECONDS))throw new IOException("Target not ready within 10 seconds");getLogger().info("[MUX-DIAG] Forwarding Minecraft stream for player "+id);sess.send((byte)4,id,prefix);try(InputStream in=p.getInputStream()){byte[] b=new byte[8192];int n;while(running&&(n=in.read(b))!=-1)sess.send((byte)4,id,Arrays.copyOf(b,n));}}catch(Exception e){getLogger().warning("[MUX-DIAG] Player "+id+" forwarding ended: "+e.getClass().getSimpleName()+": "+e.getMessage());}finally{players.remove(id);playerRoutes.remove(id);readyMap.remove(id);try{sess.send((byte)5,id,new byte[0]);}catch(IOException ignored){}try{p.close();}catch(IOException ignored){}}}
 private void closePlayer(long id){Socket p=players.remove(id);playerRoutes.remove(id);CountDownLatch l=readyMap.remove(id);if(l!=null)l.countDown();if(p!=null)try{p.close();}catch(IOException ignored){}}
 private void closeRoutePlayers(String r){for(Map.Entry<Long,String> e:playerRoutes.entrySet())if(r.equals(e.getValue()))closePlayer(e.getKey());}
 private final class Session{final String route;final Socket socket;final DataOutputStream out;final Object lock=new Object();Session(String r,Socket s,DataOutputStream o){route=r;socket=s;out=o;}boolean open(){return socket.isConnected()&&!socket.isClosed();}void send(byte t,long id,byte[] b)throws IOException{synchronized(lock){if(!open())throw new IOException("Tunnel closed");out.writeByte(t);out.writeLong(id);out.writeInt(b.length);out.write(b);out.flush();}}void close(){try{socket.close();}catch(IOException ignored){}}}
 @Override public void onDisable(){running=false;for(Session s:sessions.values())s.close();for(Socket s:players.values())try{s.close();}catch(IOException ignored){}for(ServerSocket s:listeners)try{s.close();}catch(IOException ignored){}pool.shutdownNow();}
}
